# One shared isolated repository; data-kind classification never grants consumer scope.
$lock = @'
# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "walkdir"
version = "2.5.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
dependencies = [
 "same-file",
]
'@
$base = Commit-Fixture 'Cargo.lock' $lock 'fixture data'
Check 'Cargo lock dependency names are data, not an executable reader' (-not (Test-DocsHaveSemanticConsumers $repo $base @('reports/VALIDATION.md')))
if (-not $LockfileOnly) {
    foreach ($version in @(3, 4)) {
        $base = Commit-Fixture 'Cargo.lock' ($lock.Replace('version = 4', ('version = ' + $version))) 'fixture data'
        Check ('Cargo lock v' + $version + ' known complete data is not a reader') (-not (Test-DocsHaveSemanticConsumers $repo $base @('reports/VALIDATION.md')))
    }
    foreach ($bad in @(
        ($lock.Replace('version = 4','VERSION = 4')),
        ($lock.Replace('[[package]]','[[PACKAGE]]')),
        ($lock.Replace('name =','NAME =')),
        ($lock + "`ncommand = 'walkdir()'"),
        ($lock + "`nname = 'duplicate'"),
        ($lock -replace 'version = 4', 'version = 5'),
        ($lock -replace 'same-file', 'reports/VALIDATION.md'),
        ($lock + "`nread_dir('.')"),
        ($lock -replace '\]\s*$', '')
    )) {
        $base = Commit-Fixture 'Cargo.lock' $bad 'fixture data'
        Check 'unsupported or document-referencing Cargo content stays unknown' (Test-DocsHaveSemanticConsumers $repo $base @('reports/VALIDATION.md'))
    }
    $null = Commit-Fixture 'Cargo.lock' $lock 'fixture data'
    foreach ($source in @(
        'for entry in walkdir::WalkDir::new(".") {}',
        'let text = std::fs::read_to_string("reports/VALIDATION.md")?; assert!(text.contains("accepted"));',
        'let bytes = std::fs::read("reports/VALIDATION.md")?; let text = std::str::from_utf8(&bytes)?; assert_eq!(text, expected);',
        'copy("reports/VALIDATION.md", "package/validation.md");',
        'hash_file("reports/VALIDATION.md");'
    )) {
        $base = Commit-Fixture 'reader.rs' $source 'fixture reader'
        Check 'real walker, semantic UTF8 assertion, copy or hash remains unsafe or unknown' (Test-DocsHaveSemanticConsumers $repo $base @('reports/VALIDATION.md'))
    }
}
